style.css:
@-moz-document domain("google.com"), domain("google.com.br") {
/* Fundo principal em verde escuro */
    body, html, #main, #cnt, .g {
        background-color: #0d1f12 !important;
        color: #e0f2e9 !important;
    }

    /* Links de busca em verde claro */
    a, h3 {
        color: #2ecc71 !important;
    }

    /* Barra de pesquisa */
    input[name="q"], form {
        background-color: #1b3822 !important;
        color: #ffffff !important;
    }
}
